import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import API from "../services/api";
import "./Dashboard.css";


function Dashboard(){

 const navigate = useNavigate();

 const [usuario,setUsuario] = useState("");
 const [compras,setCompras] = useState(0);
 const [gasto,setGasto] = useState(0);

 useEffect(()=>{

  const data = JSON.parse(localStorage.getItem("usuario"));

  if(!data){
   navigate("/login");
   return;
  }

  setUsuario(data.usuario);

  cargarEstadisticas(data.id_usuario);

 },[]);



 const cargarEstadisticas = async(id)=>{

  try{

   const res = await API.get(`/usuario/estadisticas/${id}`);

   setCompras(res.data.compras);
   setGasto(res.data.gasto);

  }catch(error){

   console.log("Error cargando estadísticas");

  }

 };



 const cerrarSesion = ()=>{

  localStorage.removeItem("usuario");

  navigate("/login");

 };



 return(

  <div className="dashboard">


   <div className="header">

    <h1>Bienvenido, {usuario}</h1>
    <p>Panel de Control - Usuarios</p>

   </div>



   <div className="stats">

    <div className="card">

     <h2>{compras}</h2>
     <p>Compras Realizadas</p>

    </div>

    <div className="card">

     <h2>${gasto.toLocaleString()}</h2>
     <p>Gasto Total</p>

    </div>

   </div>



   {/* CATALOGO Y COMPRAS */}

   <h3 className="section">Catálogo y Compras</h3>

   <div className="menu">

    <div className="menu-item" onClick={()=>navigate("/catalogo")}>

     <span>💎</span>

     <div>
      <h4>Comprar Esmeraldas</h4>
      <p>Explora nuestro catálogo premium</p>
     </div>

    </div>



    <div className="menu-item" onClick={()=>navigate("/favoritos")}>

     <span>⭐</span>

     <div>
      <h4>Favoritos</h4>
      <p>Tus esmeraldas guardadas</p>
     </div>

    </div>



    <div className="menu-item" onClick={()=>navigate("/historial")}>

     <span>📋</span>

     <div>
      <h4>Historial de Compras</h4>
      <p>Revisa tus pedidos anteriores</p>
     </div>

    </div>

   </div>



   {/* MI CUENTA */}

   <h3 className="section">Mi Cuenta</h3>

   <div className="menu">

    <div className="menu-item" onClick={()=>navigate("/perfil")}>

     <span>👤</span>

     <div>
      <h4>Editar Perfil</h4>
     </div>

    </div>



    <div className="menu-item" onClick={()=>navigate("/soporte")}>

     <span>📞</span>

     <div>
      <h4>Contactar Soporte</h4>
     </div>

    </div>



    <div className="menu-item" onClick={()=>navigate("/faq")}>

     <span>❓</span>

     <div>
      <h4>Preguntas Frecuentes</h4>
     </div>

    </div>

   </div>



   {/* BOTON CERRAR SESION */}

   <div className="logout">

    <button onClick={cerrarSesion}>
     Cerrar Sesión
    </button>

   </div>


  </div>

 );

}

export default Dashboard;
